<template>
	<view class="index">

		<!-- 查看账号 -->
		<uni-popup ref="popup">
			<view class="popup-content">
				<view class="account-box">
					<view class="account-title">报名</view>
					<view class="account-desc">{{item.title}}</view>
					<view class="acc-label">姓名</view>
					<view class="acc-item">
						<text class="iconfont icon-wode2"></text>
						<view class="acc-value">
							<input type="text" v-model="name" class="input" placeholder="请输入">
						</view>
					</view>
					<view class="acc-label">手机号</view>
					<view class="acc-item">
						<text class="iconfont icon-shouji4"></text>
						<view class="acc-value">
							<input type="text" v-model="phone" class="input" placeholder="请输入">
						</view>
					</view>
					<view class="btn-box">
						<view class="acc-close" @click="close">关闭</view>
						<view class="acc-sub" @click="sub">提交</view>
					</view>
				</view>
			</view>
		</uni-popup>
	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo,
		copyText
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		registerActivity
	} from '@/api/index.js'
	import {
		checkTel
	} from '@/utils/rules.js'
	export default {
		props: {
			accMaskBool: {
				type: Boolean,
				default: false
			},
			item: {
				type: Object,
				default: () => {}
			}
		},
		watch: {
			accMaskBool() {
				if (this.accMaskBool) {
					this.open()
				} else {
					this.close()
				}
			},
		},
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				name: '',
				phone: '',
			};
		},
		computed: {

		},
		mounted() {

		},
		components: {

		},
		onLoad() {

		},
		created() {

		},
		// 触底的事件
		onReachBottom() {

		},
		methods: {
			copy(text) {
				copyText(text)
			},

			open() {
				this.$refs.popup.open('center')
			},

			close() {
				this.$refs.popup.close()
				this.$emit('accWatch', false)
			},
			async sub() {
				if (this.name == '') return toast('请填写姓名')
				if (this.phone == '') return toast('请填写手机号')
				if (!checkTel(this.phone)) return toast('手机号有误')
				let _data = await registerActivity(this.item.activityId, this.name, this.phone);
				if (_data.code == 200) {
					toast(_data.msg)
					if (_data.data.needPay == false) {
						setTimeout(() => {
							this.close()
						}, 1500)
					} else {
						// const param = {
						// 	orderSn: _data.data.orderId,
						// 	couponId: '',
						// 	payAmount: this.item.price,
						// 	productName: this.item.title,
						// 	type: 2
						// }
						toast('支付功能正在完善...')
					}
				}
			},
			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

<style scoped lang="scss">
	.index {

		.account-box {
			width: 640rpx;
			background-color: #ffffff;
			border-radius: 20rpx;
			padding: 50rpx 30rpx;

			.btn-box {
				width: 100%;
				display: flex;
				justify-content: space-between;
				align-items: center;
				padding-top: 50rpx;

				.acc-close {
					width: 48%;
					height: 70rpx;
					background-image: linear-gradient(92deg,
							#c6c6c6 0%,
							#91918c 100%);
					border-radius: 34rpx;
					text-align: center;
					line-height: 70rpx;
					font-size: 28rpx;
					color: #000000;
				}

				.acc-sub {
					width: 48%;
					height: 70rpx;
					background-image: linear-gradient(92deg,
							#63b8ff 0%,
							#1f88f6 100%);
					border-radius: 34rpx;
					text-align: center;
					line-height: 70rpx;
					font-size: 28rpx;
					color: #ffffff;
				}
			}



			.tips {
				width: 100%;
				height: 73rpx;
				background-color: #fff8e1;
				border-radius: 14rpx;
				padding: 0 24rpx;
				display: flex;
				justify-content: flex-start;
				align-items: center;
				font-size: 24rpx;
				color: #bd8135;
				margin-top: 25rpx;

				.icon--zhuyi {
					font-size: 38rpx;
					color: #ffc052;
					margin-right: 10rpx;
				}
			}

			.acc-item {
				width: 100%;
				height: 79rpx;
				background-color: #f8f9fc;
				border-radius: 16rpx;
				border: solid 2rpx #dedfe1;
				display: flex;
				justify-content: space-between;
				align-items: center;
				padding-left: 24rpx;
				padding-right: 15rpx;

				.acc-btn {
					width: 101rpx;
					height: 50rpx;
					background-image: linear-gradient(90deg,
							#61b7ff 0%,
							#2c90f7 100%);
					border-radius: 6rpx;
					font-size: 28rpx;
					color: #ffffff;
					text-align: center;
					line-height: 50rpx;
				}

				.acc-value {
					flex: 1;
					font-size: 30rpx;
