						color: #333333;
						height: 48rpx;
					}
				}

				.iconfont {
					font-size: 42rpx;
					color: #888c99;
				}
			}

			.acc-label {
				width: 100%;
				font-size: 28rpx;
				color: #888c99;
				padding-top: 35rpx;
				padding-bottom: 20rpx;
			}

			.account-desc {
				width: 100%;
				text-align: center;
				font-size: 28rpx;
				color: #1f89f6;
				padding-top: 15rpx;
			}

			.account-title {
				width: 100%;
				text-align: center;
				font-size: 32rpx;
				color: #2b2e48;
				font-weight: bold;
				padding-top: 10rpx;
			}
		}

	}
</style>